argv:
$ErrorActionPreference='Continue'
$o=[ordered]@{at=(Get-Date).ToUniversalTime().ToString('o')}
$procs=@(Get-CimInstance Win32_Process -Filter "Name = 'tunnel-client.exe'" -ErrorAction SilentlyContinue)
$o.clientRunning=($procs.Count -gt 0)
$o.clientCount=$procs.Count
$o.clientPids=@($procs|Select-Object -ExpandProperty ProcessId)
try {
 $s=Invoke-RestMethod 'http://127.0.0.1:8080/api/status' -TimeoutSec 4
 $msg=[string]$s.tunnel_metadata_error
 $m=[regex]::Match($msg,'(?<!\d)(400|401|403|404|409|424|429|500|502|503)(?!\d)')
 $o.tunnelId=$s.control_plane_tunnel_id
 $o.metadataErrorPresent=($msg.Length -gt 0)
 $o.metadataHttpCode=if($m.Success){$m.Value}else{'none_or_unclassified'}
 $o.routeKind=$s.control_plane_route.kind
 $o.uptimeSeconds=$s.uptime_seconds
} catch {$o.status='unavailable'}
try {$r=Invoke-WebRequest 'http://127.0.0.1:8080/readyz' -UseBasicParsing -TimeoutSec 3;$o.localReady=($r.StatusCode -eq 200)} catch {$o.localReady=$false}
try {
 $metrics=(Invoke-WebRequest 'http://127.0.0.1:8080/metrics' -UseBasicParsing -TimeoutSec 3).Content
 $o.poll=@($metrics -split [char]10 | Where-Object {$_ -match '^(commands_poll_(cycles_total|errors_total|last_successful_timestamp_seconds))(\{[^}]*\})?\s+[-+0-9.eE]+'} | Select-Object -First 18 | ForEach-Object {[regex]::Replace($_,'\{[^}]*\}','{LABELS_REDACTED}')})
}catch{$o.poll=@('unavailable')}
$o|ConvertTo-Json -Depth 4 -Compress
